-- Sample listings so the site looks alive before real inventory is loaded.
-- Paste into Supabase → SQL Editor → Run (once). Delete them any time from Admin → Listings.
-- Samples have listing_by = NULL, so Sofia (which only searches listing_by NOT NULL) never offers them.

alter table public.properties add column if not exists is_sample boolean not null default false;
alter table public.properties alter column listing_by drop not null;

with s(title, title_es, description, description_es, type, property_type, price, bedrooms, bathrooms, area, parking, location, furnishing_status, amenities, featured, img) as (values
  ('Ocean-view 2BR in Punta Pacífica', '2 recámaras con vista al mar en Punta Pacífica', 'Sample listing. Bright corner unit with floor-to-ceiling windows over the bay, full-amenity tower.', 'Propiedad de muestra. Unidad esquinera con ventanales sobre la bahía, torre con todas las amenidades.', 'rent', 'apartment', 2400, 2, 2, 125, 2, 'punta-pacifica', 'furnished', '["pool","gym","security","oceanView"]', true, 'sample-01'),
  ('Family house with garden, Costa del Este', 'Casa familiar con jardín, Costa del Este', 'Sample listing. Four bedrooms, private garden and quiet street close to international schools.', 'Propiedad de muestra. Cuatro recámaras, jardín privado y calle tranquila cerca de colegios internacionales.', 'sale', 'house', 685000, 4, 4, 340, 3, 'costa-del-este', 'linea_blanca', '["garden","security","storage"]', true, 'sample-02'),
  ('Modern studio near Calle 50', 'Estudio moderno cerca de Calle 50', 'Sample listing. Efficient layout, walk to the financial district.', 'Propiedad de muestra. Distribución eficiente, a pasos del distrito financiero.', 'rent', 'studio', 950, 1, 1, 48, 1, 'obarrio', 'furnished', '["gym","security","ac"]', false, 'sample-03'),
  ('Penthouse with bay terrace', 'Penthouse con terraza a la bahía', 'Sample listing. Double-height living room and a wraparound terrace facing the Cinta Costera.', 'Propiedad de muestra. Sala a doble altura y terraza envolvente frente a la Cinta Costera.', 'sale', 'penthouse', 1250000, 4, 5, 420, 4, 'avenida-balboa', 'furnished', '["pool","gym","oceanView","terrace"]', true, 'sample-04'),
  ('Restored colonial loft', 'Loft colonial restaurado', 'Sample listing. Exposed brick, high ceilings and a rooftop above the plazas of the old town.', 'Propiedad de muestra. Ladrillo a la vista, techos altos y azotea sobre las plazas del casco antiguo.', 'sale', 'apartment', 390000, 1, 2, 110, 0, 'casco-viejo', 'furnished', '["terrace","ac"]', false, 'sample-05'),
  ('2BR steps from Vía Argentina', '2 recámaras a pasos de Vía Argentina', 'Sample listing. Renovated kitchen, balcony and a walkable street full of cafés.', 'Propiedad de muestra. Cocina renovada, balcón y una calle caminable llena de cafés.', 'rent', 'apartment', 1350, 2, 2, 95, 1, 'el-cangrejo', 'linea_blanca', '["gym","security","terrace"]', false, 'sample-06'),
  ('Green house in Clayton', 'Casa entre verde en Clayton', 'Sample listing. Three bedrooms surrounded by trees, near the City of Knowledge.', 'Propiedad de muestra. Tres recámaras rodeadas de árboles, cerca de la Ciudad del Saber.', 'rent', 'house', 3200, 3, 3, 260, 2, 'clayton', 'empty', '["garden","petFriendly"]', true, 'sample-07'),
  ('Golf-view residence in Santa María', 'Residencia con vista al golf en Santa María', 'Sample listing. Spacious low-rise residence overlooking the fairway in a gated community.', 'Propiedad de muestra. Amplia residencia de baja altura frente al campo, en comunidad cerrada.', 'sale', 'apartment', 820000, 3, 4, 290, 3, 'santa-maria', 'linea_blanca', '["pool","gym","security","terrace"]', false, 'sample-08'),
  ('Balcony 3BR in San Francisco', '3 recámaras con balcón en San Francisco', 'Sample listing. Family layout near Parque Omar and Multiplaza.', 'Propiedad de muestra. Distribución familiar cerca del Parque Omar y Multiplaza.', 'rent', 'apartment', 1900, 3, 2, 140, 2, 'san-francisco', 'linea_blanca', '["pool","security","playground"]', false, 'sample-09'),
  ('New townhouse in Panamá Pacífico', 'Townhouse nuevo en Panamá Pacífico', 'Sample listing. Three levels, small yard and parks within walking distance.', 'Propiedad de muestra. Tres niveles, patio y parques a poca distancia.', 'sale', 'house', 265000, 3, 3, 180, 2, 'panama-pacifico', 'empty', '["garden","playground","petFriendly"]', false, 'sample-10'),
  ('Bay-view apartment in Paitilla', 'Apartamento con vista a la bahía en Paitilla', 'Sample listing. Generous floor plan in an established building, minutes from everything.', 'Propiedad de muestra. Planta amplia en edificio consolidado, a minutos de todo.', 'rent', 'apartment', 2100, 3, 3, 185, 2, 'paitilla', 'furnished', '["pool","oceanView","security"]', false, 'sample-11'),
  ('Boutique-building flat, Coco del Mar', 'Apartamento en edificio boutique, Coco del Mar', 'Sample listing. Only four units per floor, quiet street near the coast.', 'Propiedad de muestra. Solo cuatro unidades por piso, calle tranquila cerca de la costa.', 'sale', 'apartment', 455000, 3, 3, 175, 2, 'coco-del-mar', 'linea_blanca', '["pool","gym","elevator"]', false, 'sample-12')
), ins as (
  insert into public.properties (title, title_es, description, description_es, type, property_type, price, bedrooms, bathrooms, area, parking, location, furnishing_status, property_amenities, featured, status, listing_by, is_sample)
  select title, title_es, description, description_es, type, property_type, price, bedrooms, bathrooms, area, parking, location, furnishing_status, amenities::jsonb, featured, 'active', null, true from s
  returning id, title
)
insert into public.property_images (property_id, image_url, display_order)
select ins.id, '/samples/' || s.img || '.jpg', 0 from ins join s on s.title = ins.title;
